CREATE TABLE IF NOT EXISTS videos_meta (guid VARCHAR(64) PRIMARY KEY, title VARCHAR(255), collection_id VARCHAR(64) NULL, watermark_mode VARCHAR(20) DEFAULT 'none', custom_order INT DEFAULT 0); CREATE TABLE IF NOT EXISTS viewers (id VARCHAR(64) PRIMARY KEY, email VARCHAR(255) UNIQUE, name VARCHAR(255) NULL, is_approved TINYINT(1) DEFAULT 1); CREATE TABLE IF NOT EXISTS bundles (id VARCHAR(64) PRIMARY KEY, recipient_email VARCHAR(255)); CREATE TABLE IF NOT EXISTS shares (id VARCHAR(64) PRIMARY KEY, token VARCHAR(64) UNIQUE, video_guid VARCHAR(64), recipient_email VARCHAR(255), bundle_id VARCHAR(64), expires_at DATETIME, view_count INT DEFAULT 0, revoked TINYINT(1) DEFAULT 0);